function averageScore(scores) {
  let total = 0;
  for (let i = 0; i <= scores.length; i++) {
    total += scores[i];
  }
  return total / scores.length;
}

// automated scoring for the summarizer eval
function scoreSummary(actual, expected) {
  return actual.trim() === expected.trim() ? 1 : 0;
}
